import { assign, createActor, createMachine } from 'xstate';

const wizard = createMachine({
  context: { accountId: undefined },
  initial: 'select',
  guards: { validAmount: ({ context }) => Boolean(context.accountId) },
  states: {
    select:  { on: { CHOSEN: { target: 'amount', actions: assign(({ event }) => ({ accountId: event.id })) } } },
    amount:  { on: { NEXT:   { target: 'confirm', guard: 'validAmount' } } },
    confirm: { on: { SUBMIT: 'done' } },
    done:    { type: 'final' },
  },
});
const actor = createActor(wizard);
actor.start();          // actor.send({ type: 'CHOSEN', id }) drives the steps

const steps = Object.freeze({
  select:  (flow, e) => (e.id ? ((flow.id = e.id), 'amount') : 'select'),
  amount:  (flow, e) => (e.valid ? 'confirm' : 'amount'),
  confirm: (flow, e) => (e.submit ? 'done' : 'confirm'),
  done:    (_flow, _e) => 'done',
});
function dispatch(flow, event) {
  const next = steps[flow.step](flow, event);
  if (!(next in steps)) throw new Error('illegal step ' + next);
  flow.step = next;
}
